// ===== 1) Entradas =====
const clientes = $('Webhook - Dados Clientes').first().json.body.clientes;  // enviados pelo Python
const csv = $input.first().json.data;                      // texto do data.csv

// ===== 2) CSV -> lista de produtos =====
const linhas = csv.trim().split('\n');
const cabecalho = linhas.shift().trim().split(',');
const produtos = linhas.map(l => {
  const v = l.trim().split(',');
  const p = Object.fromEntries(cabecalho.map((c, i) => [c.trim(), (v[i] ?? '').trim()]));
  p.minimo = Number(p.minimo);
  return p;
});

// ===== 3) Funções auxiliares =====
function parseBRL(valor) {            // "R$ 12.500,00" -> 12500
  if (!valor) return 0;
  const s = String(valor)
    .replace('R$', '')
    .replace(/\./g, '')
    .replace(',', '.')
    .replace(/[^\d.]/g, '')
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function formatBRL(n) {               // 1000 -> "R$ 1.000,00"
  return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
          .replace(/\u00A0/g, ' ');
}

function escolherProduto(perfil, saldo) {
  const doPerfil = produtos.filter(p => p.perfil === perfil);
  if (doPerfil.length === 0) return { produto: null, motivo: 'perfil_nao_encontrado' };

  const possiveis = doPerfil.filter(p => p.minimo <= saldo);
  if (possiveis.length > 0) {
    // maior mínimo que o saldo comporta (empate: o primeiro do CSV)
    const melhor = possiveis.reduce((a, b) => (b.minimo > a.minimo ? b : a));
    return { produto: melhor, motivo: 'saldo_ok' };
  }
  // saldo menor que todos os mínimos: sugere o de menor entrada
  const menor = doPerfil.reduce((a, b) => (b.minimo < a.minimo ? b : a));
  return { produto: menor, motivo: 'saldo_insuficiente' };
}

// ===== 4) Um item por cliente =====
return clientes.map(c => {
  const saldoNum = parseBRL(c.saldo);
  const { produto, motivo } = escolherProduto(c.perfil, saldoNum);

  let mensagem_base;
  if (motivo === 'saldo_ok') {
    mensagem_base = `${c.nome}, indo direto ao ponto: para o perfil ${c.perfil}, **${produto.produto}** (mínimo ${formatBRL(produto.minimo)}). Você tem ${formatBRL(saldoNum)}, então dá pra aplicar. Rentabilidade: ${produto.rentabilidade}.`;
  } else if (motivo === 'saldo_insuficiente') {
    mensagem_base = `${c.nome}, para o perfil ${c.perfil}, a opção de menor entrada é **${produto.produto}** (mínimo ${formatBRL(produto.minimo)}). Seu saldo atual é ${formatBRL(saldoNum)}, então ainda falta um pouco para aplicar. Rentabilidade: ${produto.rentabilidade}.`;
  } else {
    mensagem_base = `${c.nome}, não encontramos opções de investimento para o perfil ${c.perfil}.`;
  }

  return { json: {
    email_to: String(c.email || '').trim(),
    nome: c.nome,
    perfil: c.perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: produto ? {
      perfil: produto.perfil,
      produto: produto.produto,
      minimo: produto.minimo,
      rentabilidade: produto.rentabilidade
    } : null,
    motivo,
    mensagem_base,
    copy_rules: {
      idioma: 'pt-BR',
      tom: 'amigável e profissional',
      tamanho: 'curto (4-6 linhas)',
      evitar: ['promessas de ganho', 'garantias', 'linguagem agressiva']
    }
  }};
});

