const cliente = $('Code in JavaScript - Junção').item.json;

const bloco = ($json.content || []).find(b => b.type === 'text');
let bruto = bloco ? bloco.text : '';

// pega só o trecho entre a primeira "{" e a última "}"
const ini = bruto.indexOf('{');
const fim = bruto.lastIndexOf('}');
if (ini !== -1 && fim > ini) bruto = bruto.slice(ini, fim + 1);

let subject, text_body;
try {
  const j = JSON.parse(bruto);
  subject = j.subject;
  text_body = j.text_body;
} catch (e) {}

return {
  json: {
    email_to: cliente.email_to,
    nome: cliente.nome,
    subject: subject || `Sugestão de investimento para o seu perfil ${cliente.perfil}`,
    text_body: text_body || cliente.mensagem_base.replace(/\*\*/g, ''),
    origem: text_body ? 'ia' : 'fallback',   
  }
};
